const AppendTextBranchInvalidResponse sdkgo.BranchID = "invalidResponse"
const AppendTextBranchDefect sdkgo.BranchID = sdkgo.DefectBranchID

var AppendTextDefinition = sdkgo.MutationDefinition{
	Operation: sdkgo.OperationRef{ConnectorID: ConnectorID, OperationID: "appendText"},
	Branches: []sdkgo.BranchDefinition{
		{ID: AppendTextBranchAppended, Description: "The document ends with the requested text, appended by this attempt or an earlier attempt of the same Step execution."},
		{ID: AppendTextBranchRevisionChanged, Description: "The document changed after the required revision and does not end with the requested text; nothing was written.", Optional: true},
		{ID: AppendTextBranchNotFound, Description: "The document does not exist or the connection cannot see it.", Optional: true},
		{ID: AppendTextBranchProviderRejected, Description: "Google conclusively rejected the change, such as a connection without edit access.", Optional: true},
		{ID: AppendTextBranchInvalidResponse, Description: "Google returned an invalid or oversized document response.", Optional: true},
		{ID: AppendTextBranchDefect, Description: "Local input, connection configuration, or connector definition is invalid.", Optional: true},
	},
	StepDefaults: sdkgo.StepDefaults{
		ExecuteMethodTimeout: time.Duration(30000000000), HeartbeatTimeout: time.Duration(0),
		ExecuteRetry:      &dex.RetryPolicy{InitialInterval: time.Duration(1000000000), BackoffCoefficient: 2, MaximumInterval: time.Duration(30000000000), MaximumAttempts: 5, TotalDuration: time.Duration(120000000000)},
		ExecuteDurability: dex.StepDurabilityAsync,
	},
}

type AppendTextResult = sdkgo.MutationResult[AppendTextOutput]

type AppendTextStepConfig[IN any] struct {
	sdkgo.MutationFactoryConfigMarker `connector:"factory=mutation"`
	connectorID                       struct{}                                               `connector:"connectorId=google-docs"`
	operationID                       struct{}                                               `connector:"operationId=appendText"`
	StepType                          string                                                 `connector:"stepType"`
	Annotations                       sdkgo.StepAnnotations                                  `connector:"annotations"`
	ConfigurationUI                   sdkgo.ConnectorConfigurationUI                         `connector:"configurationUI"`
	Connection                        Connection                                             `connector:"connection"`
	ConnectionName                    string                                                 `connector:"connectionName"`
	MapToOperationInput               func(IN) AppendTextInput                               `connector:"mapToOperationInput"`
	Appended                          sdkgo.Target[AppendTextResult]                         `connector:"branch=appended"`
	RevisionChanged                   sdkgo.Target[AppendTextResult]                         `connector:"branch=revisionChanged,optional"`
	NotFound                          sdkgo.Target[AppendTextResult]                         `connector:"branch=notFound,optional"`
	ProviderRejected                  sdkgo.Target[AppendTextResult]                         `connector:"branch=providerRejected,optional"`
	InvalidResponse                   sdkgo.Target[AppendTextResult]                         `connector:"branch=invalidResponse,optional"`
	Defect                            sdkgo.Target[AppendTextResult]                         `connector:"branch=defect,optional"`
	ResultAttribute                   *dex.Attribute[sdkgo.MutationResult[AppendTextOutput]] `connector:"resultAttribute"`
	StepOptionsOverride               *dex.StepOptions                                       `connector:"stepOptionsOverride"`
}

func NewAppendTextStep[IN any](config AppendTextStepConfig[IN]) sdkgo.MutationStep[IN, AppendTextInput, AppendTextOutput] {
	if err := config.Connection.validateOperations(); err != nil {
		panic(err)
	}
	if config.ConnectionName != config.Connection.reference.Name {
		panic(fmt.Errorf("google-docs connector Step ConnectionName %q must equal its connection's name %q", config.ConnectionName, config.Connection.reference.Name))
	}
	return sdkgo.MustNewMutationStep(sdkgo.MutationStepConfig[IN, AppendTextInput, AppendTextOutput]{
		StepType: config.StepType, Annotations: config.Annotations,
		ConfigurationUI: config.ConfigurationUI,
		Operation:       config.Connection.operations.AppendText(), Connection: config.Connection.reference,
		MapToOperationInput: config.MapToOperationInput,
		Branches: func() []sdkgo.BranchTarget[AppendTextResult] {
			branches := make([]sdkgo.BranchTarget[AppendTextResult], 0, 6)
			if config.Appended.HasStep() {
				branches = append(branches, config.Appended.BranchTarget(AppendTextBranchAppended))
			}
			if config.RevisionChanged.HasStep() {
				branches = append(branches, config.RevisionChanged.BranchTarget(AppendTextBranchRevisionChanged))
			}
			if config.NotFound.HasStep() {
				branches = append(branches, config.NotFound.BranchTarget(AppendTextBranchNotFound))
			}
			if config.ProviderRejected.HasStep() {
				branches = append(branches, config.ProviderRejected.BranchTarget(AppendTextBranchProviderRejected))
			}
			if config.InvalidResponse.HasStep() {
				branches = append(branches, config.InvalidResponse.BranchTarget(AppendTextBranchInvalidResponse))
			}
			if config.Defect.HasStep() {
				branches = append(branches, config.Defect.BranchTarget(AppendTextBranchDefect))
			}
			return branches
		}(),
		ResultAttribute:     config.ResultAttribute,
		StepOptionsOverride: config.StepOptionsOverride,
	})
}
